def _wait_for_output(self):
        """
        Check if output matches banner.

        .. warning::
            Waiting for I/O completion. It does not work on Windows. Sorry.
        """
        if self.is_running():
            out, err = self.read_io()
            if not err:
                return out
            else:
                raise Exception(
                    'Failed to start process. Error:\n%s' % err)

